#nullable enable

namespace Allocation.Slices.Allocation;

/// <summary>
/// A rejection from a decider that is NOT behind an HTTP route.
///
/// The generated GWT scaffold guesses "a 400 with ProblemDetails" for every <c>then="error: X"</c>, because
/// the generator cannot tell a command somebody types from a command a trigger issues. For issue-grant and
/// release-slot nobody types anything: the trigger issues them in process, so there is no request to give a
/// status code to, and inventing an HTTP route to have one would invent public surface the model does not
/// draw. The rule name is still the outcome, exactly as it is in ProblemDetails.Title — so
/// <c>then="error: AlreadyIssued"</c> asserts the same NAME either way, which is what makes the two
/// transports comparable at all.
/// </summary>
public sealed record SliceOutcome(bool Accepted, string? Error = null, string? Detail = null)
{
    public static SliceOutcome Ok() => new(true);
    public static SliceOutcome Rejected(string error, string detail) => new(false, error, detail);

    public override string ToString() => Accepted ? "accepted" : $"{Error}: {Detail}";
}
